window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a3fa2a79a5eb64e3"]={"versions": [{"id": "FIG-a3fa2a79a5eb64e3", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichten- und Schnittstellendiagramm (Layered Architecture &amp; Component Interaction Overview).\n</li><li><strong>Technischer Zweck:</strong> Darstellung der strukturellen Einbettung des BSW-Moduls <code>Firewall</code> in den Kommunikations-, Treiber- und Security-Stack der AUTOSAR Classic Platform (ab Release R21-11 / R23-11).\n</li><li><strong>Funktionale Einordnung:</strong> Das Diagramm verortet die <code>Firewall</code> auf der Abstraktions- und Serviceebene. Es zeigt die operative Bindung an die Kommunikationsabstraktion (<code>EthIf</code>) zur Ingress-/Egress-Paketfilterung sowie die Anbindung an systemweite Steuerungs- (<code>BswM</code>) und Überwachungsinstanzen (<code>IdsM</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Module (Bottom-Up)</h5>\n<ol class=\"fig-list\"><li><strong>Microcontroller-Ebene ($\\mu\\text{C}$):</strong>\n<ul class=\"fig-list\"><li><code>Ethernet</code>: On-Chip Ethernet-MAC/Controller.\n</li><li><code>MII</code> (Media Independent Interface): Physische/mediale Schnittstelle zur Anbindung externer Controller oder Switches.\n</li><li><code>External Ethernet Controller</code>: Externer MAC/Switch-Baustein außerhalb des SoC.\n</li></ul>\n</li><li><strong>MCAL / Treiber-Schicht (Drivers):</strong>\n<ul class=\"fig-list\"><li><strong>I/O Drivers:</strong>\n<ul class=\"fig-list\"><li><code>DIO Driver</code>: Digitale I/O-Pins (GPIO) zur Hardware-Steuerung (z. B. Reset-, Power- und Interrupt-Leitungen von PHY/Switch).\n</li></ul>\n</li><li><strong>Communication Drivers:</strong>\n<ul class=\"fig-list\"><li><code>Ethernet Driver</code> (<code>Eth</code>): Hardwarenaher Treiber für den internen MAC-Controller.\n</li><li><code>Handler / Driver</code>: Steuer- und Bustreiber (z. B. <code>Spi</code> oder Memory-Mapped I/O) zur Konfiguration externer Controller/Switches.\n</li></ul>\n</li></ul>\n</li><li><strong>Communication Hardware Abstraction:</strong>\n<ul class=\"fig-list\"><li><code>Ethernet Interface</code> (<code>EthIf</code>): Zentrale Abstraktionsschicht, die Controller-, Transceiver- und Switch-Treiber logisch bündelt und obere Schichten von Hardware-Spezifika entkoppelt.\n</li><li><code>Ethernet Switch Driver</code> (<code>EthSwt</code>): Ansteuerung und Port-Management für Ethernet-Switches.\n</li><li><code>Ethernet Transceiver Driver</code> (<code>EthTrcv</code>): PHY-Management (Link-Status, Auto-Negotiation, Power Modes).\n</li></ul>\n</li><li><strong>Security &amp; System Services:</strong>\n<ul class=\"fig-list\"><li><code>Firewall</code>: Autonomes BSW-Modul zur zustandsbasierten oder statischen Filterung von Ethernet-Frames (L2 bis L4).\n</li><li><code>BswM</code> (Basic Software Mode Manager): Zentraler Modus-Manager der Plattform.\n</li><li><code>IdsM</code> (Intrusion Detection System Manager): BSW-Service zur Aggregation, Qualifizierung und Filterung sicherheitsrelevanter Anomalien.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong><code>EthIf</code> $\\longleftrightarrow$ <code>Firewall</code> (Bidirektional):</strong>\n<ul class=\"fig-list\"><li><code>EthIf</code> übergibt empfangene Frames oder auszusendende Frames zur Inspektion an die Firewall (Callout-/Filter-Interface).\n</li><li>Die <code>Firewall</code> liefert einen synchronen Filterentscheid (<code>PASS</code> vs. <code>DROP</code>) an <code>EthIf</code> zurück.\n</li></ul>\n</li><li><strong><code>BswM</code> ⟶ <code>Firewall</code> (<code>Firewall state</code>):</strong>\n<ul class=\"fig-list\"><li>Unidirektionaler Steuerpfad zur Umschaltung des Firewall-Betriebszustands (z. B. Initialisierung, Bypass-Modus, selektive Regelsatzumschaltung je nach Fahrzeug-/ECU-Betriebszustand).\n</li></ul>\n</li><li><strong><code>Firewall</code> ⟶ <code>IdsM</code> (<code>Security events</code>):</strong>\n<ul class=\"fig-list\"><li>Unidirektionaler Meldepfad via standardisierter Security-Event-API (<code>IdsM_SetSecurityEvent</code>). Wird getriggert bei verworfenen Paketen, unautorisierten MAC/IP-Adressen oder erkannten Anomalien.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Ingress-Paketprüfung (Rx-Pfad)</h5>\n<ol class=\"fig-list\"><li><strong>Frame-Empfang:</strong> Ein Frame gelangt über den On-Chip MAC oder den externen Controller via <code>Eth</code> in den RX-Puffer.\n</li><li><strong>Indikation:</strong> <code>Eth</code> meldet den Frame via <code>EthIf_RxIndication()</code> an das <code>EthIf</code>.\n</li><li><strong>Firewall-Hook:</strong> Bevor der Frame an obere Protokollschichten (<code>TcpIp</code>, <code>SomeIpXf</code>, <code>SoAd</code>) oder andere Switch-Ports weitergeleitet wird, ruft <code>EthIf</code> die Prüfroutine der <code>Firewall</code> auf.\n</li><li><strong>Verifikationsschleife:</strong> Die Firewall prüft Header-Felder (EtherType, VLAN-ID, MAC-Adressen, IPv4/IPv6-Header, TCP/UDP-Ports) gegen die aktuell aktiven Filterregeln.\n</li><li><strong>Entscheidungszweige:</strong>\n<ul class=\"fig-list\"><li><strong>Verdict = PASS:</strong> <code>EthIf</code> setzt die reguläre Demultiplexierung und Weiterleitung im Stack fort.\n</li><li><strong>Verdict = DROP:</strong> <code>EthIf</code> verwirft den Frame unverzüglich und gibt den Rx-Puffer frei.\n</li><li><strong>Security Event Trigger:</strong> Die <code>Firewall</code> meldet die Regelverletzung synchron oder entkoppelt an den <code>IdsM</code> (<code>IdsM_SetSecurityEvent(EventId, ContextData)</code>).\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Moduswechsel via Mode Management</h5>\n<ol class=\"fig-list\"><li><code>BswM</code> detektiert einen Zustandswechsel (z. B. Übergang von <em>Normal Operation</em> zu <em>Diagnostic / Flashing</em>).\n</li><li><code>BswM</code> führt eine konfigurierte Aktion aus und setzt den Betriebsmodus der <code>Firewall</code> über eine Modus-Anforderungs-API.\n</li><li>Die <code>Firewall</code> aktiviert den entsprechenden Regelsatz atomar, um ohne Frame-Verlust im laufenden Betrieb zwischen permissiven und restriktiven Policies zu wechseln.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Stack-Konfiguration (<code>EthIf</code> &amp; <code>Firewall</code>):</strong>\n<ul class=\"fig-list\"><li>Im <code>EthIf</code> muss der Firewall-Support explizit per Konfigurationsparameter (<code>EthIfFirewallSupport = TRUE</code>) einkompiliert werden. Fehlt dieser, werden Frames ungeprüft geroutet/nach oben gereicht.\n</li><li>Filterregeln (<code>FirewallRule</code>, <code>FirewallFilterRuleSet</code>) müssen vollständig in ARXML spezifiziert werden. Die Zuweisung zu Interfaces und Switch-Ports erfordert deterministische Referenzen auf <code>EthIfController</code> bzw. <code>EthIfSwitchPortGroup</code>.\n</li></ul>\n</li><li><strong>Ausführungs- und Latenzanforderungen (Echtzeit-Budget):</strong>\n<ul class=\"fig-list\"><li>Die Firewall-Prüfung liegt im synchronen Rx-Pfad des <code>EthIf</code>. Filteralgorithmen müssen O(1)- oder streng deterministisches O(n)-Laufzeitverhalten aufweisen.\n</li><li>Keine dynamische Speicherallokation, keine blockierenden Operationen und keine langwierigen kryptografischen Prüfungen innerhalb des Filter-Hooks, um Rx-Pufferüberläufe und Frame-Drops legitimer Pakete zu vermeiden.\n</li></ul>\n</li><li><strong>Security-Event-Rate-Limiting (IdsM-Interaktion):</strong>\n<ul class=\"fig-list\"><li>Bei DoS-Angriffen (Flooding ungültiger Pakete) darf die Firewall den <code>IdsM</code> nicht überlasten. Entwickler müssen im <code>IdsM</code> geeignete Filter- und Aggregationsstrategien (Thresholding, Context Sampling) konfigurieren.\n</li></ul>\n</li><li><strong>Hardware-Offloading:</strong>\n<ul class=\"fig-list\"><li>Ist ein intelligenter Hardware-Switch vorhanden (<code>EthSwt</code>), können Teile der L2/VLAN-Filterung direkt in die Switch-Hardware (Access Control Lists / TCAM) delegiert werden, während komplexe L3/L4-Inspektionen in der BSW-<code>Firewall</code> verbleiben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d28837567f45e802", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichten- und Schnittstellendiagramm (Layered Architecture &amp; Component Interaction Overview).\n</li><li><strong>Technischer Zweck:</strong> Darstellung der strukturellen Einbettung des BSW-Moduls <code>Firewall</code> in den Kommunikations-, Treiber- und Security-Stack der AUTOSAR Classic Platform (ab Release R24-11).\n</li><li><strong>Funktionale Einordnung:</strong> Das Diagramm verortet die <code>Firewall</code> auf der Abstraktions- und Serviceebene. Es zeigt die operative Bindung an die Kommunikationsabstraktion über den <code>L-SDU Router</code> zur Ingress-/Egress-Paketfilterung sowie die Anbindung an systemweite Steuerungs- (<code>BswM</code>) und Überwachungsinstanzen (<code>IdsM</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten &amp; Module (Bottom-Up)</h5>\n<ol class=\"fig-list\"><li><strong>Microcontroller-Ebene ($\\mu\\text{C}$):</strong>\n<ul class=\"fig-list\"><li><code>Ethernet</code>: On-Chip Ethernet-MAC/Controller.\n</li><li><code>MII</code> (Media Independent Interface): Physische/mediale Schnittstelle zur Anbindung externer Controller oder Switches.\n</li><li><code>External Ethernet Controller</code>: Externer MAC/Switch-Baustein außerhalb des SoC.\n</li></ul>\n</li><li><strong>MCAL / Treiber-Schicht (Drivers):</strong>\n<ul class=\"fig-list\"><li><strong>I/O Drivers:</strong>\n<ul class=\"fig-list\"><li><code>DIO Driver</code>: Digitale I/O-Pins (GPIO) zur Hardware-Steuerung (z. B. Reset-, Power- und Interrupt-Leitungen von PHY/Switch).\n</li></ul>\n</li><li><strong>Communication Drivers:</strong>\n<ul class=\"fig-list\"><li><code>Ethernet Driver</code> (<code>Eth</code>): Hardwarenaher Treiber für den internen MAC-Controller.\n</li><li><code>Handler / Driver</code>: Steuer- und Bustreiber (z. B. <code>Spi</code> oder Memory-Mapped I/O) zur Konfiguration externer Controller/Switches.\n</li></ul>\n</li></ul>\n</li><li><strong>Communication Hardware Abstraction:</strong>\n<ul class=\"fig-list\"><li><code>L-SDU Router</code>: Routing- und Filterungs-Kopplungsinstanz für Ethernet L-SDUs oberhalb des Interface-Treibers.\n</li><li><code>Ethernet Interface</code> (<code>EthIf</code>): Zentrale Abstraktionsschicht, die Controller-, Transceiver- und Switch-Treiber logisch bündelt und obere Schichten von Hardware-Spezifika entkoppelt.\n</li><li><code>Ethernet Switch Driver</code> (<code>EthSwt</code>): Ansteuerung und Port-Management für Ethernet-Switches.\n</li><li><code>Ethernet Transceiver Driver</code> (<code>EthTrcv</code>): PHY-Management (Link-Status, Auto-Negotiation, Power Modes).\n</li></ul>\n</li><li><strong>Security &amp; System Services:</strong>\n<ul class=\"fig-list\"><li><code>Firewall</code>: Autonomes BSW-Modul zur zustandsbasierten oder statischen Filterung von Ethernet-Frames/L-SDUs (L2 bis L4).\n</li><li><code>BswM</code> (Basic Software Mode Manager): Zentraler Modus-Manager der Plattform.\n</li><li><code>IdsM</code> (Intrusion Detection System Manager): BSW-Service zur Aggregation, Qualifizierung und Filterung sicherheitsrelevanter Anomalien.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong><code>L-SDU Router</code> $\\longleftrightarrow$ <code>Firewall</code> (Bidirektional):</strong>\n<ul class=\"fig-list\"><li><code>L-SDU Router</code> übergibt L-SDUs zur Inspektion an die Firewall (Callout-/Filter-Interface).\n</li><li>Die <code>Firewall</code> liefert einen synchronen Filterentscheid (<code>PASS</code> vs. <code>DROP</code>) an den <code>L-SDU Router</code> zurück.\n</li></ul>\n</li><li><strong><code>BswM</code> ⟶ <code>Firewall</code> (<code>Firewall state</code>):</strong>\n<ul class=\"fig-list\"><li>Unidirektionaler Steuerpfad zur Umschaltung des Firewall-Betriebszustands (z. B. Initialisierung, Bypass-Modus, selektive Regelsatzumschaltung je nach Fahrzeug-/ECU-Betriebszustand).\n</li></ul>\n</li><li><strong><code>Firewall</code> ⟶ <code>IdsM</code> (<code>Security events</code>):</strong>\n<ul class=\"fig-list\"><li>Unidirektionaler Meldepfad via standardisierter Security-Event-API (<code>IdsM_SetSecurityEvent</code>). Wird getriggert bei verworfenen Paketen, unautorisierten MAC/IP-Adressen oder erkannten Anomalien.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Ingress-Paketprüfung (Rx-Pfad)</h5>\n<ol class=\"fig-list\"><li><strong>Frame-Empfang:</strong> Ein Frame gelangt über den On-Chip MAC oder den externen Controller via <code>Eth</code> in den RX-Puffer.\n</li><li><strong>Indikation:</strong> <code>Eth</code> meldet den Frame via <code>EthIf_RxIndication()</code> an das <code>EthIf</code>, welches die L-SDU an den <code>L-SDU Router</code> weiterreicht.\n</li><li><strong>Firewall-Hook:</strong> Der <code>L-SDU Router</code> übernimmt die L-SDU und ruft vor dem weiteren Routing bzw. der Weiterleitung an obere Protokollschichten oder Switch-Ports die Prüfroutine der <code>Firewall</code> auf.\n</li><li><strong>Verifikationsschleife:</strong> Die Firewall prüft Header-Felder (EtherType, VLAN-ID, MAC-Adressen, IPv4/IPv6-Header, TCP/UDP-Ports) gegen die aktuell aktiven Filterregeln.\n</li><li><strong>Entscheidungszweige:</strong>\n<ul class=\"fig-list\"><li><strong>Verdict = PASS:</strong> Der <code>L-SDU Router</code> setzt das reguläre Routing und die Weiterleitung im Stack fort.\n</li><li><strong>Verdict = DROP:</strong> Die L-SDU wird verworfen und der Puffer freigegeben.\n</li><li><strong>Security Event Trigger:</strong> Die <code>Firewall</code> meldet die Regelverletzung synchron oder entkoppelt an den <code>IdsM</code> (<code>IdsM_SetSecurityEvent(EventId, ContextData)</code>).\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Moduswechsel via Mode Management</h5>\n<ol class=\"fig-list\"><li><code>BswM</code> detektiert einen Zustandswechsel (z. B. Übergang von <em>Normal Operation</em> zu <em>Diagnostic / Flashing</em>).\n</li><li><code>BswM</code> führt eine konfigurierte Aktion aus und setzt den Betriebsmodus der <code>Firewall</code> über eine Modus-Anforderungs-API.\n</li><li>Die <code>Firewall</code> aktiviert den entsprechenden Regelsatz atomar, um ohne Frame-Verlust im laufenden Betrieb zwischen permissiven und restriktiven Policies zu wechseln.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Stack-Konfiguration (<code>L-SDU Router</code> / <code>EthIf</code> &amp; <code>Firewall</code>):</strong>\n<ul class=\"fig-list\"><li>Im Kommunikations-Stack muss der Firewall-Support für das L-SDU-Routing explizit konfiguriert werden. Fehlt dieser, werden L-SDUs ungeprüft weitergeleitet bzw. geroutet.\n</li><li>Filterregeln (<code>FirewallRule</code>, <code>FirewallFilterRuleSet</code>) müssen vollständig in ARXML spezifiziert werden. Die Zuweisung erfordert deterministische Referenzen auf die Routing-Pfade, Schnittstellen und Switch-Ports.\n</li></ul>\n</li><li><strong>Ausführungs- und Latenzanforderungen (Echtzeit-Budget):</strong>\n<ul class=\"fig-list\"><li>Die Firewall-Prüfung liegt im synchronen Pfad des <code>L-SDU Router</code>. Filteralgorithmen müssen O(1)- oder streng deterministisches O(n)-Laufzeitverhalten aufweisen.\n</li><li>Keine dynamische Speicherallokation, keine blockierenden Operationen und keine langwierigen kryptografischen Prüfungen innerhalb des Filter-Hooks, um Pufferüberläufe und Frame-Drops legitimer Pakete zu vermeiden.\n</li></ul>\n</li><li><strong>Security-Event-Rate-Limiting (IdsM-Interaktion):</strong>\n<ul class=\"fig-list\"><li>Bei DoS-Angriffen (Flooding ungültiger Pakete) darf die Firewall den <code>IdsM</code> nicht überlasten. Entwickler müssen im <code>IdsM</code> geeignete Filter- und Aggregationsstrategien (Thresholding, Context Sampling) konfigurieren.\n</li></ul>\n</li><li><strong>Hardware-Offloading:</strong>\n<ul class=\"fig-list\"><li>Ist ein intelligenter Hardware-Switch vorhanden (<code>EthSwt</code>), können Teile der L2/VLAN-Filterung direkt in die Switch-Hardware (Access Control Lists / TCAM) delegiert werden, während komplexe L3/L4-Inspektionen in der BSW-<code>Firewall</code> verbleiben.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a3fa2a79a5eb64e3", "to": "FIG-d28837567f45e802", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Communication Hardware Abstraction</code>: Neue Komponente <code>L-SDU Router</code> oberhalb von <code>Ethernet Interface</code> hinzugefügt.\n</li><li>Schnittstelle <code>Firewall</code>: Der bidirektionale Interaktionspfad zur <code>Firewall</code> bindet nicht mehr direkt an das <code>Ethernet Interface</code> an, sondern verbindet nun <code>L-SDU Router</code> und <code>Firewall</code>.\n</li><li>Diagramm-Layout: <code>BswM</code> und <code>IdsM</code> vertikal nach oben versetzt, Verbindungspfeile <code>Firewall state</code> und <code>Security events</code> entsprechend nach oben verlängert.\n</li></ul>"}]};
